    background: #1d4ed8;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.625rem 1.5rem;
    border-radius: 6px;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-back:hover {
    background: #f3f4f6;
}

.btn-add {
    background: white;
    color: #2563eb;
    border: 1px dashed #2563eb;
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-size: 0.875rem;
    cursor: pointer;
    width: 100%;
    margin-bottom: 1rem;
    transition: background 0.15s;
}

.btn-add:hover {
    background: #eff6ff;
}

.btn-remove {
    background: transparent;
    color: #dc2626;
    border: 1px solid #dc2626;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.75rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-remove:hover {
    background: #fef2f2;
}

.btn-edit {
    background: transparent;
    color: #2563eb;
    border: none;
    padding: 0.25rem 0.5rem;
    font-size: 0.875rem;
    cursor: pointer;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #1d4ed8;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px !important;
}

.character-count {
    text-align: right;
    font-size: 0.75rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1f2937;
}

.review-details {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-details dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-details dd {
    margin: 0;
    font-size: 0.875rem;
    color: #1f2937;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
    font-size: 0.875rem;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    font-size: 0.875rem;
    white-space: pre-wrap;
    color: #374151;
}

/* Error & Confirmation */
.error-message {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

.confirmation {
    text-align: center;
    padding: 3rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
}

.confirmation h2 {
    color: #16a34a;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.125rem;
    color: #374151;
}
"}

toolArgs.file_text:
namespace sv_b4153887f2d947a5887cca10d18285f5.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_b4153887f2d947a5887cca10d18285f5.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="error-message">@_errorMessage</div>
    }

    @* Step Content *@
    @if (_submitted)
    {
        <div class="confirmation">
            <h2>✓ Application Submitted!</h2>
            <p>Your application has been received. Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        switch (_currentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReview()
                break;
        }
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() => @<div class="step-content">
    <h2>Personal Information</h2>
    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
    </div>
    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
    </div>
    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
    </div>
    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="_address" placeholder="Enter your address" />
    </div>
    <div class="form-actions">
        <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
            @if (_isValidating) { <span>Validating...</span> } else { <span>Next</span> }
        </button>
    </div>
</div>; }

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() => @<div class="step-content">
    <h2>Work History</h2>
    @for (int i = 0; i < _workEntries.Count; i++)
    {
        var index = i;
        <div class="work-entry-card">
            <div class="work-entry-header">
                <h3>Position @(index + 1)</h3>
                @if (_workEntries.Count > 1)
                {
                    <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
            </div>
            <div class="form-group">
                <label>Company Name *</label>
                <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
            </div>
            <div class="form-group">
                <label>Job Title *</label>
                <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Start Date *</label>
                    <input type="date" @bind="_workEntries[index].StartDate" />
                </div>
                <div class="form-group">
                    <label>End Date</label>
                    <input type="date" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                    <label class="checkbox-label">
                        <input type="checkbox" @bind="_workEntries[index].IsCurrent" /> Currently working here
                    </label>
                </div>
            </div>
            <div class="form-group">
                <label>Description</label>
                <textarea @bind="_workEntries[index].Description" placeholder="Describe your responsibilities"></textarea>
            </div>
        </div>
    }
    <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
    </div>
</div>; }

@* Step 3: References *@
@{ RenderFragment RenderReferences() => @<div class="step-content">
    <h2>References</h2>
    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        <div class="reference-card">
            <div class="work-entry-header">
                <h3>Reference @(index + 1)</h3>
                @if (_references.Count > 2)
                {
                    <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Manager, Colleague" />
                </div>
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="_references[index].Email" placeholder="Email" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="_references[index].Phone" placeholder="Phone" />
                </div>
            </div>
        </div>
    }
    @if (_references.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromReferences">Next</button>
    </div>
</div>; }

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() => @<div class="step-content">
    <h2>Cover Letter</h2>
    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="cover-letter-textarea" @bind="_coverLetter" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit for this position..."></textarea>
        <div class="character-count">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
    </div>
    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
    </div>
</div>; }

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReview() => @<div class="step-content">
    <h2>Review & Submit</h2>

    <div class="review-section">
        <div class="review-header">
            <h3>Personal Information</h3>
            <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
        </div>
        <dl class="review-details">
            <dt>Full Name</dt><dd>@_fullName</dd>
            <dt>Email</dt><dd>@_email</dd>
            <dt>Phone</dt><dd>@_phone</dd>
            <dt>Address</dt><dd>@_address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Work History</h3>
            <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
        </div>
        @foreach (var entry in _workEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>References</h3>
            <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
        </div>
        @foreach (var reference in _references)
        {
            <div class="review-reference">
                <strong>@reference.Name</strong> (@reference.Relationship)<br />
                <span>@reference.Email | @reference.Phone</span>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h3>Cover Letter</h3>
            <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
        </div>
        <p class="review-cover-letter">@_coverLetter</p>
    </div>

    <div class="form-actions">
        <button class="btn-back" @onclick="PreviousStep">Back</button>
        <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
            @if (_isSubmitting) { <span>Submitting...</span> } else { <span>Submit Application</span> }
        </button>
    </div>
</div>; }

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private int _highestCompletedStep = -1;
    private string _errorMessage = string.Empty;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1: Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2: Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string _coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step <= _highestCompletedStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            _currentStep = step;
            _errorMessage = string.Empty;
        }
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
        _errorMessage = string.Empty;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(_email);
            if (!isValidEmail)
            {
                _errorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        AdvanceStep();
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = string.Empty;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for all positions.";
                return;
            }
        }

        AdvanceStep();
    }

    private void NextFromReferences()
    {
        _errorMessage = string.Empty;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        AdvanceStep();
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }

        AdvanceStep();
    }

    private void AdvanceStep()
    {
        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;
        _currentStep++;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty
                )).ToList()),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

