+}
+
+.step-connector {
+    flex: 1;
+    height: 2px;
+    background: #d1d5db;
+    margin: 0 0.25rem;
+    margin-bottom: 1.5rem;
+    min-width: 20px;
+}
+
+.step-connector.completed {
+    background: #16a34a;
+}
+
+.checkmark {
+    font-size: 1rem;
+}
+
+/* Form Styles */
+.step-content {
+    background: white;
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    padding: 2rem;
+}
+
+.step-content h2 {
+    margin-top: 0;
+    margin-bottom: 1.5rem;
+    color: #1f2937;
+}
+
+.form-group {
+    margin-bottom: 1rem;
+}
+
+.form-group label {
+    display: block;
+    margin-bottom: 0.375rem;
+    font-weight: 500;
+    color: #374151;
+    font-size: 0.875rem;
+}
+
+.form-group input[type="text"],
+.form-group input[type="email"],
+.form-group input[type="tel"],
+.form-group input[type="date"],
+.form-group textarea {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #d1d5db;
+    border-radius: 6px;
+    font-size: 0.875rem;
+    box-sizing: border-box;
+    transition: border-color 0.15s;
+}
+
+.form-group input:focus,
+.form-group textarea:focus {
+    outline: none;
+    border-color: #2563eb;
+    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
+}
+
+.form-group textarea {
+    min-height: 80px;
+    resize: vertical;
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+.checkbox-label {
+    display: inline-flex !important;
+    align-items: center;
+    gap: 0.5rem;
+    font-weight: normal !important;
+    margin-top: 0.5rem;
+    cursor: pointer;
+}
+
+.checkbox-label input[type="checkbox"] {
+    width: auto;
+}
+
+/* Cards for work entries and references */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: #f9fafb;
+}
+
+.work-entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #374151;
+}
+
+/* Buttons */
+.form-actions {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #e5e7eb;
+}
+
+.btn-next,
+.btn-submit {
+    background: #2563eb;
+    color: white;
+    border: none;
+    padding: 0.625rem 1.5rem;
+    border-radius: 6px;
+    font-size: 0.875rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.btn-next:hover,
+.btn-submit:hover {
+    background: #1d4ed8;
+}
+
+.btn-next:disabled,
+.btn-submit:disabled {
+    background: #93c5fd;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    background: white;
+    color: #374151;
+    border: 1px solid #d1d5db;
+    padding: 0.625rem 1.5rem;
+    border-radius: 6px;
+    font-size: 0.875rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.btn-back:hover {
+    background: #f3f4f6;
+}
+
+.btn-add {
+    background: white;
+    color: #2563eb;
+    border: 1px dashed #2563eb;
+    padding: 0.5rem 1rem;
+    border-radius: 6px;
+    font-size: 0.875rem;
+    cursor: pointer;
+    width: 100%;
+    margin-bottom: 1rem;
+    transition: background 0.15s;
+}
+
+.btn-add:hover {
+    background: #eff6ff;
+}
+
+.btn-remove {
+    background: transparent;
+    color: #dc2626;
+    border: 1px solid #dc2626;
+    padding: 0.25rem 0.75rem;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.btn-remove:hover {
+    background: #fef2f2;
+}
+
+.btn-edit {
+    background: transparent;
+    color: #2563eb;
+    border: none;
+    padding: 0.25rem 0.5rem;
+    font-size: 0.875rem;
+    cursor: pointer;
+    text-decoration: underline;
+}
+
+.btn-edit:hover {
+    color: #1d4ed8;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 200px !important;
+}
+
+.character-count {
+    text-align: right;
+    font-size: 0.75rem;
+    color: #6b7280;
+    margin-top: 0.25rem;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #1f2937;
+}
+
+.review-details {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-details dt {
+    font-weight: 500;
+    color: #6b7280;
+    font-size: 0.875rem;
+}
+
+.review-details dd {
+    margin: 0;
+    font-size: 0.875rem;
+    color: #1f2937;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.75rem 0;
+    border-bottom: 1px solid #f3f4f6;
+    font-size: 0.875rem;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    font-size: 0.875rem;
+    white-space: pre-wrap;
+    color: #374151;
+}
+
+/* Error & Confirmation */
+.error-message {
+    background: #fef2f2;
+    border: 1px solid #fecaca;
+    color: #dc2626;
+    padding: 0.75rem 1rem;
+    border-radius: 6px;
+    margin-bottom: 1rem;
+    font-size: 0.875rem;
+}
+
+.confirmation {
+    text-align: center;
+    padding: 3rem;
+    background: #f0fdf4;
+    border: 1px solid #bbf7d0;
+    border-radius: 8px;
+}
+
+.confirmation h2 {
+    color: #16a34a;
+    margin-bottom: 1rem;
+}
+
+.confirmation p {
+    font-size: 1.125rem;
+    color: #374151;
+}
+
